// Background preparation only. Parent browsers read saved JSON and never run this exporter.
import fs from'node:fs';import path from'node:path';import{createHash}from'node:crypto';import{fileURLToPath}from'node:url';
const folder=path.dirname(fileURLToPath(import.meta.url)),local=process.argv.includes('--local'),retryWarnings=process.argv.includes('--retry-warnings'),only=Number(process.argv.find(a=>a.startsWith('--class='))?.split('=')[1]||process.env.IELTS_UI_CLASS||0);
const config=JSON.parse(fs.readFileSync(local?folder+'/private/inventory.json':folder+'/classes.json')).classes;
const secret=local?null:JSON.parse(process.env.IELTS_UI_PARENT_ROSTER||'null');if(!local&&!Array.isArray(secret))throw Error('PRIVATE_ROSTER_REQUIRED');
const classes=config.filter(c=>(!only||c.number===only)&&(!local||c.number!==48)),allTokens=(local?config.flatMap(c=>c.profiles):secret).map(p=>p.token),hash=v=>createHash('sha256').update(v).digest('hex');
const key=(a,e={})=>a+'|'+JSON.stringify(Object.fromEntries(Object.entries(e).sort(([a],[b])=>a.localeCompare(b))));
async function pool(rows,n,fn){let i=0;await Promise.all(Array.from({length:Math.min(n,rows.length)},async()=>{while(i<rows.length)await fn(rows[i++]);}));}
const reports=[],pupilWorkers=Number(process.argv.find(a=>a.startsWith('--pupils='))?.split('=')[1]||2),detailWorkers=Number(process.argv.find(a=>a.startsWith('--details='))?.split('=')[1]||3);
for(const c of classes){const out=local?folder+'/candidate/'+c.route+'/data/writing':path.resolve(c.route+'/data/writing');fs.mkdirSync(out,{recursive:true});
 if(local){const seed=folder+'/generated/'+c.number+'/public/writing';if(fs.existsSync(seed))fs.cpSync(seed,out,{recursive:true,force:false,errorOnExist:false,filter:p=>!p.endsWith('export-report.json')});}
 const roster=(local?c.profiles:secret.filter(p=>p.number===c.number)).filter(p=>(!local||fs.existsSync(folder+'/private/profiles/'+c.number+'/'+p.hash+'.json'))&&(!retryWarnings||(()=>{try{return JSON.parse(fs.readFileSync(out+'/'+p.hash+'.json')).sourceWarnings?.length>0;}catch(_){return false;}})()));let completed=0;
 async function call(p,action,extra={}){const endpoints=action.startsWith('writing_assessment')?[...c.endpoints].reverse():c.endpoints;let last;
  for(const endpoint of endpoints){try{const u=new URL(endpoint);Object.entries({api:'parent1',class:c.className,token:p.token,action,...extra}).forEach(([k,v])=>u.searchParams.set(k,v));const r=await fetch(u,{signal:AbortSignal.timeout(90000)});if(!r.ok)throw Error('HTTP_'+r.status);const v=await r.json();if(v.ok!==true||v.className!==c.className||v.action!==action||v.data?.parentName!==p.name)throw Error(v.error||'SOURCE_IDENTITY_MISMATCH');const raw=JSON.stringify(v.data);if(allTokens.some(t=>raw.includes(t)))throw Error('PARENT_CREDENTIAL_IN_RESPONSE');return v.data;}catch(e){last=e;}}
  throw Error(action+'_'+last.message);
 }
 await pool(roster,pupilWorkers,async p=>{try{let old;const dest=out+'/'+p.hash+'.json';try{old=JSON.parse(fs.readFileSync(dest));}catch(_){}
  if(local&&old?.name===p.name&&old.className===c.className&&!old.sourceWarnings?.length&&Date.now()-Date.parse(old.capturedAt)<3600000){reports.push({class:c.number,hash:p.hash,ok:true,reused:true});console.log(JSON.stringify({class:c.number,completed:++completed,total:roster.length,reused:true}));return;}
  let packet;if(local)packet=JSON.parse(fs.readFileSync(folder+'/private/profiles/'+c.number+'/'+p.hash+'.json'));else{const r=await fetch(c.baseUrl+p.hash+'.json',{signal:AbortSignal.timeout(30000)});if(r.status===410){reports.push({class:c.number,hash:p.hash,ok:true,revoked:true});return;}if(!r.ok)throw Error('PREPARED_PROFILE_HTTP_'+r.status);packet=await r.json();}
  if(packet.name!==p.name||packet.className!==c.className)throw Error('PREPARED_IDENTITY');
  const actions={},versions={},assets={},sourceWarnings=[];
  const previous=k=>old?.name===p.name&&old.className===c.className&&old.actions?.[k]&&!old.actions[k].staticUnavailable&&(!old.actions[k].staticAsset||fs.existsSync(out+'/'+old.actions[k].staticAsset))?old.actions[k]:null;
  const empty=action=>action==='writing'?{className:c.className,studentName:p.name,parentName:p.name,parentRosterRevision:packet.rosterRevision,reviews:[],sourceStates:[],notebookStates:[],writingPolicyStates:[]}:{schemaVersion:1,className:c.className,studentName:p.name,parentName:p.name,parentRosterRevision:packet.rosterRevision,reviews:[]};
  async function metadata(action,enabled){if(!enabled)return empty(action);const saved=previous(key(action));if(retryWarnings&&saved&&!old.sourceWarnings?.some(w=>w.action===action))return saved;try{return await call(p,action);}catch(e){if(e.message.endsWith('_INVALID_REQUEST'))return {...empty(action),sourceCapability:'not-supported'};sourceWarnings.push({action,error:e.message});return saved||{staticUnavailable:true};}}
  const capabilities=c.capabilities||{writing:true,classwork:true,assessment:true};
  [actions[key('writing')],actions[key('classwork_index')]]=await Promise.all([metadata('writing',capabilities.writing),metadata('classwork_index',capabilities.classwork)]);
  const jobs=[];for(const r of actions[key('classwork_index')].reviews||[])for(const[action,version]of[['classwork_review',r.hash],['classwork_source',r.sourceHash]])jobs.push({action,extra:{reviewKey:r.key,reviewHash:version},version});
  const descriptors=new Map((capabilities.assessment?packet.actions.profile?.student?.assessmentResults||[]:[]).flatMap(r=>r.components||[]).map(c=>c.writingAssessment).filter(d=>d?.available).map(d=>[JSON.stringify([d.assessmentKey,d.attempt,d.paper]),d]));
  for(const d of descriptors.values())for(const action of['writing_assessment','writing_assessment_source'])jobs.push({action,extra:{assessment_key:d.assessmentKey,attempt:String(d.attempt),paper:d.paper},version:d.payloadSha256});
  await pool(jobs,detailWorkers,async({action,extra,version})=>{const k=key(action,extra);versions[k]=version;if(old?.versions?.[k]===version&&previous(k)){actions[k]=previous(k);return;}let value;try{value=await call(p,action,extra);}catch(e){sourceWarnings.push({action,error:e.message});actions[k]={staticUnavailable:true};return;}const raw=JSON.stringify(value);if(raw.length>50000){const filename='asset-'+hash(raw)+'.json';assets[filename]=raw;actions[k]={staticAsset:filename};}else actions[k]=value;});
  for(const[k,value]of Object.entries(actions)){if(value.staticAsset)continue;const raw=JSON.stringify(value);if(raw.length>50000){const filename='asset-'+hash(raw)+'.json';assets[filename]=raw;actions[k]={staticAsset:filename};}}
  for(const[f,raw]of Object.entries(assets))fs.writeFileSync(out+'/'+f,raw);
  const result={schemaVersion:1,className:c.className,name:p.name,rosterRevision:packet.rosterRevision,capturedAt:new Date().toISOString(),actions,versions,sourceWarnings};if(old&&JSON.stringify(old.actions)===JSON.stringify(actions)&&JSON.stringify(old.versions)===JSON.stringify(versions)&&JSON.stringify(old.sourceWarnings||[])===JSON.stringify(sourceWarnings))result.capturedAt=old.capturedAt;fs.writeFileSync(dest,JSON.stringify(result));reports.push({class:c.number,hash:p.hash,ok:true,actions:Object.keys(actions).length,complete:sourceWarnings.length===0,warnings:sourceWarnings.length});console.log(JSON.stringify({class:c.number,completed:++completed,total:roster.length,ok:true,warnings:sourceWarnings.length}));
 }catch(e){reports.push({class:c.number,hash:p.hash,ok:false,error:e.message});console.log(JSON.stringify({class:c.number,completed:++completed,total:roster.length,ok:false,error:e.message}));}});
}
fs.writeFileSync(local?folder+'/private/writing-export-'+only+'.json':path.resolve('ielts-writing-export-report-'+only+'.json'),JSON.stringify({at:new Date().toISOString(),reports},null,2));if(reports.some(r=>!r.ok))process.exitCode=1;
